DELETE FROM AUD_PIPELINE_REPARSES WHERE REPARSE_ID IN (SELECT t.REPARSE_ID AS row_id FROM AUD_PIPELINE_REPARSES t WHERE t.PROJECT_ID=:project_id AND t.REPARSED_AT<:cutoff
AND t.REPARSE_ID<>(SELECT MAX(latest.REPARSE_ID) FROM AUD_PIPELINE_REPARSES latest WHERE latest.PIPELINE_ID=t.PIPELINE_ID)
AND (t.STATUS<>'SUCCESS' OR t.REPARSE_ID<>(SELECT MAX(good.REPARSE_ID) FROM AUD_PIPELINE_REPARSES good WHERE good.PIPELINE_ID=t.PIPELINE_ID AND good.STATUS='SUCCESS'))
AND (SELECT referencing.REPARSE_ID FROM AUD_PIPELINE_REPARSES referencing WHERE referencing.SNAPSHOT_REPARSE_ID=t.REPARSE_ID LIMIT 1) IS NULL ORDER BY t.REPARSED_AT,t.REPARSE_ID LIMIT 10000)
